932	    static private List<FType> meetParams(FGenericFunction f, List<FType> fArgs, FGenericFunction g,
933	                                          List<FType> gArgs, Map<FType, FType> parent, HasAt atF, HasAt atG) {
934	        Map<FType, List<FType>> classes = new IdentityHashMap<FType, List<FType>>();
935	        for (FType t : new ArrayList<FType>(parent.keySet())) {
936	            FType r = root(t, parent);
937	            List<FType> c = classes.get(r);
938	            if (c == null) classes.put(r, c = new ArrayList<FType>());
939	            c.add(t);
940	        }
941	        Map<FType, StaticParam> declOf = new IdentityHashMap<FType, StaticParam>();
942	        Map<FType, Boolean> ofF = new IdentityHashMap<FType, Boolean>();
943	        List<StaticParam> fps = f.getStaticParams();
944	        List<StaticParam> gps = g.getStaticParams();
945	        for (int i = 0; i < fArgs.size(); i++) {
946	            declOf.put(fArgs.get(i), fps.get(i));
947	            ofF.put(fArgs.get(i), true);
948	        }
949	        for (int j = 0; j < gArgs.size(); j++) {
950	            declOf.put(gArgs.get(j), gps.get(j));
951	            ofF.put(gArgs.get(j), false);
952	        }
953	        Environment geF = f.getWithin().extendAt(atF);
954	        Environment geG = g.getWithin().extendAt(atG);
955	        Map<FType, FType> valueOf = new IdentityHashMap<FType, FType>();
956	        Map<FType, List<FType>> made = new IdentityHashMap<FType, List<FType>>();
957	        for (Map.Entry<FType, List<FType>> e : classes.entrySet()) {
958	            FType ground = null;
959	            List<FType> params = new ArrayList<FType>();
960	            for (FType t : e.getValue()) {
961	                if (t instanceof SymbolicType && declOf.containsKey(t)) params.add(t);
962	                else if (t.isSymbolic()) continue;
963	                else if (ground == null) ground = t;
964	                else if (!ground.equals(t)) return null;
965	            }
966	            FType v;
967	            if (ground != null) v = ground;
968	            else if (params.size() >= 2) {
969	                StaticParam sp = declOf.get(params.get(0));
970	                v = new SymbolicInstantiatedType(NodeUtil.getName(sp), geF, sp);
971	                made.put(v, params);
972	            } else continue;
973	            for (FType t : e.getValue()) valueOf.put(t, v);
974	        }
975	        List<FType> meetArgs = new ArrayList<FType>(fArgs.size());
976	        for (int i = 0; i < fArgs.size(); i++) {
977	            FType a = fArgs.get(i);
978	            FType v = valueOf.containsKey(a) ? valueOf.get(a) : a;
979	            meetArgs.add(v);
980	            geF.putType(NodeUtil.getName(fps.get(i)), v);
981	        }
982	        for (int j = 0; j < gArgs.size(); j++) {
983	            FType a = gArgs.get(j);
984	            geG.putType(NodeUtil.getName(gps.get(j)), valueOf.containsKey(a) ? valueOf.get(a) : a);
985	        }
986	        Map<FType, List<FType>> bounds = new IdentityHashMap<FType, List<FType>>();
987	        for (Map.Entry<FType, List<FType>> e : made.entrySet()) {
988	            List<FType> bs = new ArrayList<FType>();
989	            for (FType p : e.getValue()) {
990	                StaticParam sp = declOf.get(p);
991	                EvalType et = new EvalType(ofF.get(p) ? geF : geG);
992	                for (FType b : et.getFTypeListFromList(sp.getExtendsClause())) {
993	                    if (b != FTypeTop.ONLY && !bs.contains(b)) bs.add(b);
994	                }
995	            }
996	            bounds.put(e.getKey(), bs);
997	        }
998	        for (Map.Entry<FType, List<FType>> e : bounds.entrySet()) {
999	            ((SymbolicInstantiatedType) e.getKey()).setExtendsAndExcludes(e.getValue(), null);
1000	        }
1001	        return meetArgs;
