1010	    static private boolean matchApart(FType a, FType b, Map<FType, FType> parent) {
1011	        if (a == b) return true;
1012	        if (a instanceof SymbolicType || b instanceof SymbolicType || a instanceof SymbolicNat
1013	            || b instanceof SymbolicNat) {
1014	            FType ra = root(a, parent);
1015	            FType rb = root(b, parent);
1016	            if (ra != rb) parent.put(ra, rb);
1017	            return true;
1018	        }
1019	        if (a instanceof GenericTypeInstance && b instanceof GenericTypeInstance && sameGeneric(a, b)) {
1020	            List<FType> xa = ((GenericTypeInstance) a).getTypeParams();
1021	            List<FType> xb = ((GenericTypeInstance) b).getTypeParams();
1022	            if (xa.size() != xb.size()) return false;
1023	            for (int i = 0; i < xa.size(); i++) {
1024	                if (!matchApart(xa.get(i), xb.get(i), parent)) return false;
1025	            }
1026	            return true;
1027	        }
1028	        return !mentionsSymbolic(a) && !mentionsSymbolic(b) && a.equals(b);
